func TestAgentSupportsSequentialModelSelectedMCPCalls(t *testing.T) {
	llm := &fakeLLM{responses: []ChatResponse{
		{Choices: []Choice{{FinishReason: "tool_calls", Message: Message{ToolCalls: []ToolCall{{
			ID: "call-create", Type: "function", Function: ToolCallFunction{Name: mcpgithub.ScheduleToolName, Arguments: `{"owner":"modelcontextprotocol","repository":"go-sdk","interval_seconds":60,"max_runs":2}`},
		}}}}}},
		{Choices: []Choice{{FinishReason: "tool_calls", Message: Message{ToolCalls: []ToolCall{{
			ID: "call-summary", Type: "function", Function: ToolCallFunction{Name: mcpgithub.SummaryToolName, Arguments: `{"schedule_id":"mon_0123456789abcdef0123456789abcdef"}`},
		}}}}}},
		{Choices: []Choice{{FinishReason: "stop", Message: Message{Content: "Мониторинг создан; два снимка сохранены, звёзды выросли на одну."}}}},
	}}
	session := &fakeSession{}
	chatAgent := New(Config{Model: "fake-model"}, llm, fakeConnector{session: session})

	result, err := chatAgent.Ask(context.Background(), "Создай мониторинг, затем покажи его сводку")
	if err != nil {
		t.Fatalf("Ask() error = %v", err)
	}
	if len(session.calls) != 2 || session.calls[0].name != mcpgithub.ScheduleToolName || session.calls[1].name != mcpgithub.SummaryToolName {
		t.Fatalf("tool calls = %+v", session.calls)
	}
	if session.calls[0].arguments["owner"] != "modelcontextprotocol" || session.calls[0].arguments["interval_seconds"].(jsonNumber).String() != "60" {
		t.Fatalf("create arguments = %#v", session.calls[0].arguments)
	}
	if len(llm.requests) != 3 || llm.requests[0].ToolChoice != "auto" || len(llm.requests[0].Tools) != 2 {
		t.Fatalf("LLM requests = %+v", llm.requests)
	}
	firstToolResult := llm.requests[1].Messages[len(llm.requests[1].Messages)-1]
	secondToolResult := llm.requests[2].Messages[len(llm.requests[2].Messages)-1]
	if firstToolResult.Role != "tool" || firstToolResult.ToolCallID != "call-create" || !strings.Contains(firstToolResult.Content, "schedule_id") {
		t.Fatalf("first tool message = %+v", firstToolResult)
	}
	if secondToolResult.Role != "tool" || secondToolResult.ToolCallID != "call-summary" || !strings.Contains(secondToolResult.Content, "5153") {
		t.Fatalf("second tool message = %+v", secondToolResult)
	}
	if result.Content == "" || len(result.Trace) != 6 || result.Trace[5].Stage != "final" {
		t.Fatalf("result = %+v", result)
	}
}

func TestMCPToolCallsReturnStructuredResultsAndIdempotentCancel(t *testing.T) {
	session, _ := testSession(t)
	created, err := session.CallTool(context.Background(), ScheduleToolName, map[string]any{
		"owner": "modelcontextprotocol", "repository": "go-sdk", "interval_seconds": 60, "max_runs": 2,
	})
	if err != nil || created.IsError || created.Structured == nil {
		t.Fatalf("schedule result = %+v, %v", created, err)
	}
	var schedule ScheduleOutput
	decodeStructured(t, created.Structured, &schedule)
	if !schedule.OK || schedule.ScheduleID == "" || schedule.Status != store.StatusActive || schedule.NextRunAt == nil {
		t.Fatalf("schedule = %+v", schedule)
	}

	listed, err := session.CallTool(context.Background(), ListToolName, map[string]any{"status": "active"})
	if err != nil || listed.IsError {
		t.Fatalf("list result = %+v, %v", listed, err)
	}
	var list ListOutput
	decodeStructured(t, listed.Structured, &list)
	if !list.OK || list.Count != 1 || list.Monitors[0].ID != schedule.ScheduleID {
		t.Fatalf("list = %+v", list)
	}

	summarized, err := session.CallTool(context.Background(), SummaryToolName, map[string]any{"schedule_id": schedule.ScheduleID})
	if err != nil || summarized.IsError {
		t.Fatalf("summary result = %+v, %v", summarized, err)
	}
	var summary SummaryOutput
	decodeStructured(t, summarized.Structured, &summary)
	if !summary.OK || summary.SnapshotCount != 0 || !summary.InsufficientData {
		t.Fatalf("summary = %+v", summary)
	}

	for i := range 2 {
		cancelled, err := session.CallTool(context.Background(), CancelToolName, map[string]any{"schedule_id": schedule.ScheduleID})
		if err != nil || cancelled.IsError {
			t.Fatalf("cancel %d = %+v, %v", i, cancelled, err)
		}
		var output CancelOutput
		decodeStructured(t, cancelled.Structured, &output)
		if !output.OK || output.Status != store.StatusCancelled || output.AlreadyCancelled != (i == 1) {
			t.Fatalf("cancel %d = %+v", i, output)
		}
	}
}

## История диалога

Web-приложение выдаёт браузеру HttpOnly session cookie и хранит последние 12 полных ходов диалога. В следующий запрос модели передаются предыдущие сообщения вместе с MCP tool calls и результатами, поэтому фразы вроде «останови созданный монитор» работают без повторного ввода ID. Кнопка «Новый диалог» очищает только историю чата; расписания и снимки MCP при этом не удаляются. История чата хранится в памяти `agent-app` и сбрасывается при его перезапуске.

Ключевые пакеты:

- `internal/mcpmulti` — агрегация каталогов и маршрутизация tool calls по нескольким MCP;
- `internal/mcpgithub`, `internal/store`, `internal/scheduler`, `internal/githubapi` — GitHub-домен;
- `internal/mcpcurrency`, `internal/currencystore`, `internal/currencyscheduler`, `internal/frankfurter`, `internal/decimal` — валютный домен;
- `internal/agent` — общий многошаговый tool-call loop;
- `internal/web` — общая панель GitHub + валюты.

func TestAgentModelSelectedPipelineAndExactTransfer(t *testing.T) {
	a, llm, dir := testPipeline(t, false)
	result, err := a.Ask(context.Background(), "Найди MCP, сделай сводку и сохрани.")
	if err != nil {
		t.Fatal(err)
	}
	if llm.step != 4 || result.Content == "" {
		t.Fatalf("incomplete loop: step=%d response=%+v", llm.step, result)
	}
	var order, ids []string
	for _, event := range result.Trace {
		if event.Stage == "model/tool_call" {
			order = append(order, event.Tool)
			ids = append(ids, event.ToolCallID)
		}
	}
	if !reflect.DeepEqual(order, []string{pipeline.SearchToolName, pipeline.SummarizeToolName, pipeline.SaveToolName}) {
		t.Fatalf("order=%v", order)
	}
	if !reflect.DeepEqual(ids, []string{"call-search", "call-summary", "call-save"}) {
		t.Fatalf("ids=%v", ids)
	}
	path := filepath.Join(dir, "mcp-summary.md")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	hash := fmt.Sprintf("%x", sha256.Sum256(data))
	var saved pipeline.SaveOutput
	for _, event := range result.Trace {
		if event.Stage == "mcp/tools/call" && event.Tool == pipeline.SaveToolName {
			encoded, _ := json.Marshal(event.Result)
			if err := json.Unmarshal(encoded, &saved); err != nil {
				t.Fatal(err)
			}
		}
	}
	if saved.SHA256 != hash || saved.Path != path {
		t.Fatalf("saved=%+v hash=%s", saved, hash)
	}
	// The summary result and save arguments must be byte-for-byte equal.
	var summary string
	var saveContent string
	for _, event := range result.Trace {
		if event.Stage == "mcp/tools/call" && event.Tool == pipeline.SummarizeToolName {
			encoded, _ := json.Marshal(event.Result)
			var out pipeline.SummarizeOutput
			_ = json.Unmarshal(encoded, &out)
			summary = out.Summary
		}
		if event.Stage == "model/tool_call" && event.Tool == pipeline.SaveToolName {
			saveContent, _ = event.Arguments["content"].(string)
		}
	}
	if summary == "" || saveContent != summary {
		t.Fatalf("summary transfer changed: %q != %q", saveContent, summary)
	}
}

func Summarize(input SummarizeInput) (SummarizeOutput, error) {
	input.Query = cleanSpace(input.Query)
	if input.Query == "" || len([]rune(input.Query)) > 300 {
		return SummarizeOutput{}, errors.New("query must contain 1 to 300 characters")
	}
	if input.MaxSentences < 1 || input.MaxSentences > 10 {
		return SummarizeOutput{}, errors.New("max_sentences must be between 1 and 10")
	}
	if len(input.Documents) > 5 {
		return SummarizeOutput{}, errors.New("documents must contain at most 5 items")
	}
	terms := meaningfulWords(input.Query)
	seen := map[string]bool{}
	all := make([]rankedSentence, 0)
	sources := make([]Source, 0, len(input.Documents))
	seenSources := map[string]bool{}
	order := 0
	for _, document := range input.Documents {
		document.Title, document.URL, document.Text = cleanSpace(document.Title), strings.TrimSpace(document.URL), cleanSpace(document.Text)
		if document.URL != "" && !seenSources[document.URL] {
			sources = append(sources, Source{Title: document.Title, URL: document.URL})
			seenSources[document.URL] = true
		}
		for _, match := range sentenceBoundary.FindAllString(document.Text, -1) {
			sentence := cleanSpace(match)
			key := strings.ToLower(strings.Trim(sentence, " .!?…"))
			if key == "" || seen[key] {
				continue
			}
			seen[key] = true
			words := meaningfulWords(sentence)
			score := len(words)
			for term := range terms {
				if words[term] {
					score += 12
				}
			}
			if len([]rune(sentence)) >= 45 && len([]rune(sentence)) <= 260 {
				score += 4
			}
			all = append(all, rankedSentence{text: sentence, order: order, score: score})
			order++
		}
	}
	warning := ""
	if len(all) == 0 {
		warning = "Недостаточно данных для составления сводки."
		return SummarizeOutput{OK: true, Query: input.Query, Sources: sources, InputDocuments: len(input.Documents), Warning: warning}, nil
	}
	ranked := append([]rankedSentence(nil), all...)
	sort.SliceStable(ranked, func(i, j int) bool {
		if ranked[i].score == ranked[j].score {
			return ranked[i].order < ranked[j].order
		}
		return ranked[i].score > ranked[j].score
	})
	count := input.MaxSentences
	if len(ranked) < count {
		count = len(ranked)
		warning = "Доступно меньше информативных предложений, чем запрошено."
	}
	chosen := append([]rankedSentence(nil), ranked[:count]...)
	sort.Slice(chosen, func(i, j int) bool { return chosen[i].order < chosen[j].order })
	parts := make([]string, len(chosen))
	for i := range chosen {
		parts[i] = chosen[i].text
	}
	return SummarizeOutput{OK: true, Query: input.Query, Summary: strings.Join(parts, " "), Sources: sources, InputDocuments: len(input.Documents), SentenceCount: len(chosen), Warning: warning}, nil
}

