// ConnectAndListTools connects to endpoint and follows every tools/list page.
func ConnectAndListTools(ctx context.Context, endpoint string) (*ConnectionResult, error) {
	transport := &mcp.StreamableClientTransport{
		Endpoint: endpoint,
		HTTPClient: &http.Client{
			Timeout: 15 * time.Second,
		},
		DisableStandaloneSSE: true,
	}
	client := mcp.NewClient(
		&mcp.Implementation{Name: "day16-mcp-client", Version: ServerVersion},
		nil,
	)

	session, err := client.Connect(ctx, transport, nil)
	if err != nil {
		return nil, fmt.Errorf("connect to MCP server: %w", err)
	}
	defer session.Close()

	result := &ConnectionResult{}
	if initialized := session.InitializeResult(); initialized != nil {
		result.ProtocolVersion = initialized.ProtocolVersion
		if initialized.ServerInfo != nil {
			result.ServerName = initialized.ServerInfo.Name
			result.ServerVersion = initialized.ServerInfo.Version
		}
	}

	params := &mcp.ListToolsParams{}
	for {
		page, err := session.ListTools(ctx, params)
		if err != nil {
			return nil, fmt.Errorf("list MCP tools: %w", err)
		}
		result.Tools = append(result.Tools, page.Tools...)
		if page.NextCursor == "" {
			break
		}
		params.Cursor = page.NextCursor
	}

	return result, nil
}

func TestConnectAndListTools(t *testing.T) {
	httpServer := httptest.NewServer(Handler())
	t.Cleanup(httpServer.Close)

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	result, err := ConnectAndListTools(ctx, httpServer.URL+"/mcp")
	if err != nil {
		t.Fatalf("ConnectAndListTools() error = %v", err)
	}
	if result.ServerName != ServerName {
		t.Fatalf("server name = %q, want %q", result.ServerName, ServerName)
	}
	if result.ProtocolVersion == "" {
		t.Fatal("protocol version is empty")
	}
	if len(result.Tools) != 1 {
		t.Fatalf("tool count = %d, want 1", len(result.Tools))
	}
	if result.Tools[0].Name != ToolName {
		t.Fatalf("tool name = %q, want %q", result.Tools[0].Name, ToolName)
	}
	if result.Tools[0].InputSchema == nil {
		t.Fatal("tool input schema is nil")
	}
}

